"""Localidade, regional, base e zona extraídas do Monitor de Variação original.
As grafias da fonte foram preservadas. Não altera o cadastro global do PRISMA.
"""
import re
import unicodedata


def normalizar(texto):
    texto = unicodedata.normalize("NFKD", str(texto or ""))
    texto = "".join(c for c in texto if not unicodedata.combining(c))
    return re.sub(r"\\s+", " ", texto).strip().upper()


