def construir_mapeamento():
    registros = {}
    for linha in FONTE.splitlines():
        regional, base, municipios = linha.split(";", 2)
        for item in municipios.split("|"):
            cidade, zona = item.rsplit(":", 1)
            chave = normalizar(cidade)
            if chave in registros:
                raise ValueError("Município repetido na tabela de regionais: " + cidade)
            registros[chave] = (regional, base, zona)
    return registros


MAPA_REGIONAIS = construir_mapeamento()


def dados_regional(cidade):
    return MAPA_REGIONAIS.get(normalizar(cidade), ("Não mapeada", "-", ""))
